public static String applyRelativePath(String path, String relativePath) {
    // Split the relative path into components
    String[] components = relativePath.split("/");
    List<String> relativeComponents = new ArrayList<>();
    for (String component : components) {
        if (!component.isEmpty()) {
            relativeComponents.add(component);
        }
    }

    // Split the full path into components
    String[] fullComponents = path.split("/");
    if (fullComponents[0].isEmpty()) {
        fullComponents[0] = "/";
    }

    // Resolve the relative path
    int i = 0;
    while (i < relativeComponents.size()) {
        String component = relativeComponents.get(i);
        if (component.equals(".")) {
            i++;
        } else if (component.equals("..")) {
            i++;
            if (i < fullComponents.length) {
                fullComponents[i] = component;
            } else {
                fullComponents[0] = component;
            }
        } else {
            fullComponents[i] = component;
            i++;
        }
    }

    // Join the full path components back together
    StringBuilder joinedPath = new StringBuilder();
    for (String component : fullComponents) {
        if (!joinedPath.isEmpty()) {
            joinedPath.append("/");
        }
        joinedPath.append(component);
    }

    return joinedPath.toString();
}
