    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            if (tokens.length != 3) {
                continue;
            }
            long timestamp = Long.parseLong(tokens[0]);
            int threadId = Integer.parseInt(tokens[1]);
            String threadName = tokens[2];
            boolean include = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    include = true;
                    break;
                }
            }
            if (include) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadName, timestamp);
                threadSnapshots.add(threadSnapshot);
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
    return threadSnapshots;
}
